const fresh=()=>({queue:[],seen:[],chapters:[],focus:'balanced',retireSince:null,retireRun:0,moveHistory:[],homes:[]});
export function stories(s){return s.story||fresh();}
function write(s){return s.story??=fresh();}
function matches(s,key){const rooms=s.lifestyle?.rooms||[];return !key||({nojob:!s.job,cinema:s.home>0&&rooms.includes('cinema'),study:s.home>0&&rooms.includes('study'),gaming:s.home>0&&rooms.includes('gaming'),guest:s.home>0&&rooms.includes('guest'),home:s.home>0,car:s.car,collection:(s.collection||[]).length>0}[key]??false);}
export function scheduleStory(s,id,origin,months=1){const p=write(s);if(!STORY_NODES[id])throw Error('이야기를 찾을 수 없습니다.');if(p.seen.includes(id)||p.queue.some(x=>x.id===id)||s.pending?.storyId===id)return;p.queue.push({id,due:due(s.month,months),origin});}
export function pruneStoryQueue(s){if(s.story)s.story.queue=s.story.queue.filter(x=>matches(s,STORY_NODES[x.id].condition));}
export function onJobChange(s){const p=write(s);p.queue=p.queue.filter(x=>STORY_NODES[x.id].group!=='retire');if(s.job){p.retireSince=null;if(s.pending?.kind==='story'&&STORY_NODES[s.pending.storyId].condition==='nojob'){s.log.push({id:s.log.length+1,month:s.month,type:'result',title:'일하는 일상으로 돌아왔다',text:'다시 일하는 선택에 따라 아직 마치지 않은 퇴사 이후의 장을 정리했습니다.'});s.pending=null;}return;}p.retireSince=s.month;p.retireRun++;scheduleStory(s,'retire-first','일을 그만둔 선택',1);}
export function onPurchaseStory(s,item){if(item.type==='home'){const p=write(s);p.homes??=[];p.homes.push({name:item.name,region:s.region,from:s.month,to:null});}const ids={home:'home-weekend',car:'car-weekend',luxury:'collection-day',experience:'travel-return',study:'study-morning',cinema:'cinema-evening',gaming:'gaming-evening',guest:'guest-visit'};const key=item.type==='room'?item.id:item.type;if(ids[key])scheduleStory(s,ids[key],item.name+'을 선택한 일상',2);}
export function trackHomeSale(s){if(s.story?.homes?.length){const home=s.story.homes.findLast(x=>x.to===null);if(home)home.to=s.month;}}
export function onLifeStory(s,kind,id,name){if(kind==='room')onPurchaseStory(s,{id,type:'room',name});if(kind==='hobby')scheduleStory(s,'hobby-'+id,name+' 체험',1);if(kind==='gift'&&id==='support')scheduleStory(s,'family-request','가족의 필요한 지출을 도운 선택',2);}
export function nextStory(s){if(!s.story){write(s);if(s.homeDetails&&s.home)scheduleStory(s,'home-weekend','이전 기록에서 보유한 '+s.homeDetails.name,0);if(s.vehicle&&s.car)scheduleStory(s,'car-weekend','이전 기록에서 보유한 '+s.vehicle.name,0);if(s.collection?.length)scheduleStory(s,'collection-day','이전 기록의 소장품',0);const rooms={cinema:'cinema-evening',study:'study-morning',gaming:'gaming-evening',guest:'guest-visit'};for(const room of s.lifestyle?.rooms||[])if(s.home&&rooms[room])scheduleStory(s,rooms[room],'이전 기록에서 꾸민 나의 공간',0);}if(!s.job&&stories(s).retireRun===0)onJobChange(s);const p=stories(s);if(!s.story)return null;
 p.queue=p.queue.filter(x=>matches(s,STORY_NODES[x.id].condition));const focus=p.focus==='self'?'space':p.focus==='social'?'social':p.focus==='active'?'active':null;
 const ready=p.queue.filter(x=>x.due<=s.month).sort((a,b)=>(STORY_NODES[a.id].group==='retire'?0:STORY_NODES[a.id].group===focus?1:2)-(STORY_NODES[b.id].group==='retire'?0:STORY_NODES[b.id].group===focus?1:2)||a.due.localeCompare(b.due));
 const selected=ready[0];if(!selected)return null;p.queue=p.queue.filter(x=>x!==selected);p.seen.push(selected.id);const node=STORY_NODES[selected.id];return {id:'story-'+selected.id,storyId:selected.id,kind:'story',category:'내 선택의 다음 장',title:node.title,text:node.text,origin:selected.origin};}
export function storyChoices(s){const node=STORY_NODES[s.pending?.storyId];return (node?.options||[]).map(o=>{const cost=Math.round(o.cost*economy(s.month).priceFactor);const next=o.next&&stories(s).seen.includes(o.next)?null:o.next;return {...o,next,cost,ending:o.ending||(!next&&o.next?'다시 이어간 나의 취향':null),detail:`${cost?moneyText(cost)+' 지출':'비용 없음'} · 만족 +${o.happy}${o.job?' · 다음 달부터 근로소득 재개':''}${next?' · 다음 이야기로 이어짐':' · 이 장의 기억 완성'}`};});}
export function resolveStory(s,id){const option=storyChoices(s).find(x=>x.id===id);if(!option||s.pending?.kind!=='story')throw Error('현재 이야기의 선택이 아닙니다.');if(option.job&&s.household?.jobReadyAt!==null&&s.household?.jobReadyAt>monthNumber(s.month))throw Error('구직 준비 기간이 끝난 뒤 선택할 수 있습니다.');if(s.cash<option.cost)throw Error('사용 가능한 현금이 부족합니다.');const p=write(s),node=s.pending.storyId,origin=s.pending.origin||'나의 선택';s.cash-=option.cost;s.happy=Math.min(100,s.happy+option.happy);if(option.job){jobTransition(s,true);onJobChange(s);}const chapter={id:node,month:s.month,title:STORY_NODES[node].title,choice:option.title,text:option.text,cost:option.cost,ending:option.ending||null,origin};p.chapters.push(chapter);s.log.push({id:s.log.length+1,month:s.month,type:'result',title:option.title,text:`${option.text} 지출 ${moneyText(option.cost)}. ${option.next?'선택이 다음 이야기로 이어집니다.':'이 장을 나의 기억으로 남겼습니다.'} 비용과 효과는 게임 가정입니다.`});s.pending=null;if(option.next)scheduleStory(s,option.next,option.title,1);return chapter;}
export function setFocus(s,id){if(s.ended)throw Error('이미 마친 삶입니다.');const f=FOCUSES.find(x=>x.id===id);if(!f)throw Error('시간의 방향을 확인해 주세요.');const p=write(s);if(p.focus===id)return;p.focus=id;s.log.push({id:s.log.length+1,month:s.month,type:'choice',title:f.name+'에 시간을 두기로 했다',text:f.text+' 급여·근로시간·비용·건강 수치는 바꾸지 않는 이야기 우선순위 설정입니다.'});}
export function validStories(s){const p=s.story;if(p===undefined)return true;const month=m=>typeof m==='string'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(m);if(!p||!FOCUSES.some(f=>f.id===p.focus)||!(p.retireSince===null||month(p.retireSince))||!Number.isInteger(p.retireRun)||p.retireRun<0)return false;
 if(!Array.isArray(p.queue)||p.queue.length>100||!p.queue.every(x=>x&&STORY_NODES[x.id]&&month(x.due)&&typeof x.origin==='string')||new Set(p.queue.map(x=>x.id)).size!==p.queue.length)return false;
 if(!Array.isArray(p.seen)||p.seen.length>100||!p.seen.every(id=>STORY_NODES[id])||new Set(p.seen).size!==p.seen.length)return false;
 if(!Array.isArray(p.chapters)||p.chapters.length>100||!p.chapters.every(x=>x&&STORY_NODES[x.id]&&month(x.month)&&['title','choice','text','origin'].every(k=>typeof x[k]==='string')&&Number.isFinite(x.cost)&&x.cost>=0&&x.cost<=1e15&&(x.ending===null||typeof x.ending==='string')))return false;
 if(p.homes!==undefined&&(!Array.isArray(p.homes)||p.homes.length>1000||!p.homes.every(h=>h&&typeof h.name==='string'&&Object.hasOwn(REGIONS,h.region)&&month(h.from)&&(h.to===null||(month(h.to)&&h.to>=h.from)))))return false;
 return Array.isArray(p.moveHistory)&&p.moveHistory.length<=1000&&p.moveHistory.every(x=>x&&Object.hasOwn(REGIONS,x.from)&&Object.hasOwn(REGIONS,x.to)&&month(x.month));}
export function moveQuote(s,region){if(!Object.hasOwn(REGIONS,region))throw Error('지역을 확인해 주세요.');const factor=economy(s.month).priceFactor,cost=Math.round(2000000*factor),rent=Math.round(REGIONS[region].rent*factor),houseBase=Math.round(s.houseBase/REGIONS[s.region].house*REGIONS[region].house);let reason='';if(s.ended)reason='이미 마친 삶입니다.';else if(region===s.region)reason='현재 살고 있는 지역입니다.';else if(s.home)reason='거주 주택을 먼저 매도한 뒤 이사해 주세요.';else if(s.cash<cost)reason='이사 비용을 낼 현금이 부족합니다.';else if(stories(s).moveHistory.some(x=>x.month===s.month))reason='이사는 월 1회 가능합니다.';return {region,cost,rent,houseBase,monthlyChange:Math.round(rent-s.rent*s.cpi),disabled:Boolean(reason),reason};}
export function moveRegion(s,region){const q=moveQuote(s,region);if(q.disabled)throw Error(q.reason);const from=s.region;s.cash-=q.cost;s.region=region;s.rent=q.rent/s.cpi;s.houseBase=q.houseBase;write(s).moveHistory.push({from,to:region,month:s.month});s.log.push({id:s.log.length+1,month:s.month,type:'choice',title:REGIONS[region].name+'에서 다시 시작하는 일상',text:`${REGIONS[from].name}에서 이사했습니다. 이사비 ${moneyText(q.cost)}. 새 월세 ${moneyText(q.rent)}. 지역별 가격과 이사비는 게임 가정이며 보증금은 미반영입니다.`});return q;}
